sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

	// First find other incidents that have the same short description field
	const shortDescFieldName = 'short_description';
    const incidentIds = [];
    const shortDescValue = current.getValue(shortDescFieldName);

    let incidentGR = new GlideRecord('incident');
    incidentGR.addActiveQuery();
    incidentGR.addQuery(shortDescFieldName, shortDescValue);
    incidentGR.addQuery('sys_id', '!=', current.getUniqueValue());
    incidentGR.query();

    while (incidentGR.next()) {
		incidentIds.push(incidentGR.getValue('number'));
    }

	// We already got the ids of the lookalike incidents
	// Lets filter incidents whose ids have not yet been added to the current incident worknotes

	const workNoteTableName = 'work_notes';
	const currentWorkNotes = [];
	const workNoteGR = new GlideRecord('sys_journal_field');
	workNoteGR.addQuery('name', 'incident');
	workNoteGR.addQuery('element', workNoteTableName);
	workNoteGR.addQuery('element_id', current.sys_id);
	workNoteGR.query();

	let unloggedIncidentIds = incidentIds;

	while (workNoteGR.next()) {
		unloggedIncidentIds = unloggedIncidentIds.filter(id => workNoteGR.getValue('value').indexOf(id) === -1);		
		currentWorkNotes.push(workNoteGR);
	}

	// Now we have the incidents which have not yet been added to the work notes
	const worknoteMessage = gs.getMessage();

	for (let id of unloggedIncidentIds) {
		current.work_notes = "Checking for duplicates...";
	}

			// Commit the changes
		current.setWorkflow(false); // CRITICAL: Prevents this Business Rule from re-triggering itself
		current.update();


})(current, previous);
